function showTab(tab) {
  ['good','warn','bad'].forEach(t => {
    document.getElementById('panel-' + t).classList.toggle('visible', t === tab);
    const btn = document.getElementById('tab-' + t);
    btn.classList.remove('active-good','active-warn','active-bad');
    if (t === tab) btn.classList.add('active-' + t);
  });
}

tool_input.new_string:
function showTab(tab) {
  ['good','warn','bad','live'].forEach(t => {
    document.getElementById('panel-' + t).classList.toggle('visible', t === tab);
    const btn = document.getElementById('tab-' + t);
    btn.classList.remove('active-good','active-warn','active-bad','active-warn');
    if (t === tab) {
      const cls = t === 'live' ? 'active-warn' : 'active-' + t;
      btn.classList.add(cls);
    }
  });
}

